-- 00_PRECHECK_CLOUD.sql — READ-ONLY 선판정 [E20261006-ITEMGT] · 빌드 2026-10-06 18:49 · 원천 사내 ZIOUI1
--  ⚠ QA · DEV 두 DB 모두 · [H-BODY] JUDGE 가 '적용'/'SKIP' 이 아니면 11 BODY 전체본을 적용하지 말고 12 수동 반영(README §4)
SET PAGESIZE 200 LINESIZE 250
COLUMN JUDGE FORMAT A120
PROMPT [E0] 접속 DB
SELECT USER USR, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','SERVER_HOST') HOST FROM DUAL;
PROMPT [H0] SPEC/BODY 상태 (SPEC 은 이번 건에서 변경 없음)
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS
 WHERE OBJECT_NAME = 'PKG_DMF0003' ORDER BY 1, 2;
PROMPT [H-SPEC] PKG_DMF0003 SPEC 지문 — 사내 81/6910 (사내 SPEC LAST_DDL 2026-10-02 11:38:28 — 저장 인자 CLOB 판)
SELECT LN || '/' || CH SPEC_FP,
       CASE WHEN LN = 81 AND CH = 6910 THEN 'OK — 사내와 같은 SPEC'
            ELSE '⚠ SPEC 이 사내와 다름 — 11 BODY 전체본 적용 금지(컴파일 불일치 위험). 12 를 수동 반영 (README §4)' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE' AND LINE > 1);
PROMPT [H-BODY] PKG_DMF0003 BODY 지문 — 전 15618/758991 (사내 10-02 20:31:56 판) · 후 15710/764484
SELECT LN || '/' || CH BODY_FP, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261006-ITEMGT]%') ITEMGT_MARK_LINES, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261006-ASISPARITY]%') ASISPARITY_MARK_LINES,
       CASE WHEN LN = 15710 AND CH = 764484 THEN 'SKIP — 이미 적용됨'
            WHEN LN = 15618 AND CH = 758991 THEN '적용 — 05 → 10 → 11 → 13 → 90'
            WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261006-ITEMGT]%') = 9 THEN 'SKIP? — 변경분은 전부 있으나 지문 상이(타 변경 병존). 90 으로 확인'
            WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%[E20261006-ASISPARITY]%') > 0 THEN '⚠ ASISPARITY 가드(비활성 8곳)가 들어 있음 — 가드를 먼저 걷어낸 뒤 12 를 수동 반영 (README §4)'
            ELSE '⚠ BODY 전체본 적용 금지 — 지문 상이(사내 누적본 미적용 또는 클라우드 전용 변경). 10 실행 후 12 를 수동 반영 (README §4)' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0003' AND TYPE='PACKAGE BODY' AND LINE > 1);
PROMPT [G1] 임시테이블 4종 · 인덱스 — 없으면 10 이 만든다 (있으면 건너뜀)
SELECT T.COLUMN_VALUE OBJ, NVL((SELECT 'EXISTS' FROM USER_OBJECTS O WHERE O.OBJECT_NAME = T.COLUMN_VALUE AND ROWNUM = 1), '없음') ST
  FROM TABLE(SYS.ODCIVARCHAR2LIST('GT_DMF3_ITEM_SINGLE_ORI', 'GT_DMF3_ITEM_SINGLE_A', 'GT_DMF3_ITEM_SINGLE_B', 'GT_DMF3_ITEM_SINGLE_V_ALL', 'IDX1_GT_DMF3_ITEM_SINGLE_V_ALL')) T;
PROMPT [G2] 권한·시노님 기준 = 기존 GT_DMF3_ITEM_SINGLE_V (10 이 같은 대상에게 같은 권한을 준다) — 사내: 권한 [('SCMP_APP', 'DELETE,INSERT,SELECT,UPDATE')] · 시노님 소유자 ['SCMP_APP']
SELECT 'GRANT' KIND, GRANTEE WHO, LISTAGG(PRIVILEGE, ',') WITHIN GROUP (ORDER BY PRIVILEGE) WHAT FROM USER_TAB_PRIVS WHERE TABLE_NAME = 'GT_DMF3_ITEM_SINGLE_V' GROUP BY GRANTEE
UNION ALL
SELECT 'SYNONYM', OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE TABLE_OWNER = USER AND TABLE_NAME = 'GT_DMF3_ITEM_SINGLE_V';
PROMPT [G3] 품목 원천 SCM_MST_ITEM_SN — 82 사업부 활성 행수 (사내 76,492행 · 0 이면 임시테이블이 비어 검증·RTF_SYS_RP 가 동작하지 않는다)
SELECT DIVISION_ID, COUNT(*) ACTIVE_ROWS, COUNT(DISTINCT ITEM_ID) ACTIVE_ITEMS FROM SCM_MST_ITEM_SN WHERE ACTIVE_FLAG = 'Y' AND DIVISION_ID = '82' GROUP BY DIVISION_ID;
